   603  bool Packet::shortenLayer(Layer* layer, int offsetInLayer, size_t numOfBytesToShorten)
   604  {
   605          if (layer == nullptr)
   606          {
   607                  PCPP_LOG_ERROR("Layer is NULL");
   608                  return false;
   609          }
   610
