   612          if (!(layer->m_Packet == this))
   613          {
   614                  PCPP_LOG_ERROR("Layer isn't allocated to this packet");
   615                  return false;
   616          }
   617
   618          // remove data from raw packet
   619          int indexOfDataToRemove = layer->m_Data + offsetInLayer - m_RawPacket->getRawData();
   620          if (!m_RawPacket->removeData(indexOfDataToRemove, numOfBytesToShorten))
   621          {
   622                  PCPP_LOG_ERROR("Couldn't remove data from packet");
   623                  return false;
   624          }
   625
