   630          Layer* curLayer = m_FirstLayer;
   631          bool passedExtendedLayer = false;
   632          while (curLayer != nullptr)
   633          {
   634                  // set the data ptr
   635                  curLayer->m_Data = (uint8_t*)dataPtr;
   636
   637                  // set a flag if arrived to the layer being shortened
   638                  if (curLayer->getPrevLayer() == layer)
   639                          passedExtendedLayer = true;
   640
   641                  // change the data length only for layers who come before the shortened layer. For layers who come after, data length isn't changed
   642                  if (!passedExtendedLayer)
   643                          curLayer->m_DataLen -= numOfBytesToShorten;
