   645                  // assuming header length of the layer that requested to be extended hasn't been enlarged yet
   646                  size_t headerLen = curLayer->getHeaderLen() - (curLayer == layer ? numOfBytesToShorten : 0);
   647                  dataPtr += headerLen;
   648                  curLayer = curLayer->getNextLayer();
   649          }
   650
   651          return true;
   652  }
